examples.css:
.b { width: 300px; padding: 20px; border: 5px solid #1e3a8a; margin-bottom: 10px; font-family: sans-serif; background: #dbeafe; }
.content { box-sizing: content-box; }  /* 350px wide */
.border  { box-sizing: border-box; }   /* 300px wide */

*, *::before, *::after { box-sizing: border-box; }
* { margin: 0; }
body { font: 16px/1.5 sans-serif; padding: 12px; }
img { max-width: 100%; display: block; }
h1 { margin-bottom: 8px; }

body { font-family: sans-serif; background: #f1f5f9; }
.c { width: 300px; background: #5e9de9; color: #fff; padding: 14px; margin: 0 auto; }
.second { background: #3cd3ad; margin: 20px 60px 0 auto; }

body { font-family: sans-serif; }
.a, .b { background: #fcd34d; padding: 10px; }
.a { margin-bottom: 40px; }
.b { margin-top: 60px; background: #86efac; }
.note { font-size: 13px; color: #555; }

.btn { display: inline-block; background: #2965f1; color: #fff; text-decoration: none; font-family: sans-serif; border-radius: 6px; }
.small { padding: 4px 8px; }
.big { padding: 16px 40px; }

.wrap { background: #e2e8f0; font-family: sans-serif; }
.pad, .mar { background: #38bdf8; color: #fff; border: 2px solid #0369a1; }
.pad { padding: 30px; }
.mar { margin: 30px; }

.shapes { display: flex; gap: 14px; align-items: center; }
i { display: block; background: linear-gradient(to right top,#051937,#004d7a,#008793,#00bf72,#a8eb12); width: 90px; height: 90px; }
.s1 { border-radius: 10px; }
.s2 { border-radius: 50%; }
.s3 { width: 150px; border-radius: 999px; }
.s4 { border-radius: 100% 0% 100% 0% / 100% 0% 100% 0%; }

p { width: 260px; font-family: sans-serif; background: #f1f5f9; padding: 8px; }
.one { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.three { display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
